function out = sequence_recurrence(a, b, p, q, n)
  % SEQUENCE_RECURRENCE Generate the first n terms of a linear recurrence sequence.
  %   out = sequence_recurrence(a, b, p, q, n) returns a column vector where
  %   x(1) = a, x(2) = b, and x(i) = p*x(i-1) + q*x(i-2) for i > 2.
  %   The output orientation matches the input orientation of 'a' and 'b'.

  if n <= 0
    out = [];
    return;
  end

  % Initialize output with the first term
  out = a;

  if n == 1
    return;
  end

  % Initialize with the second term
  out = [out; b];

  % Generate remaining terms
  for i = 3:n
    out(i) = p * out(i-1) + q * out(i-2);
  end
end

