function out = string_parse(s)
  % STRING_PARSE Parse numbers separated by commas with optional surrounding spaces.
  % Preserve input orientation.

  % Replace commas with spaces to allow flexible splitting
  s = strrep(s, ',', ' ');

  % Split by whitespace, filtering out empty strings
  parts = strsplit(s, ' ');
  parts = parts(~cellfun(@isempty, parts));

  % Convert each part to a number
  out = zeros(size(s));
  for i = 1:length(parts)
    if ~isempty(parts{i})
      out(i) = str2num(parts{i});
    end
  end
end

function out = sliding_window(x, w, s)
  % SLIDING_WINDOW Return means of valid windows of width w and stride s.
  % Preserves input orientation.

  [rows, cols] = size(x);
  out = zeros(rows, ceil(cols/w));

  for i = 1:rows
    for j = 1:ceil(cols/w)
      start_idx = (j-1)*s + 1;
      end_idx = min(start_idx + w - 1, cols);

      if start_idx <= end_idx
        window = x(i, start_idx:end_idx);
        out(i, j) = mean(window);
      end
    end
  end
end

