function out = sliding_window(x, w, s)
  % SLIDING_WINDOW Returns valid-window medians with stride s without for/while loops.
  % Preserves input orientation.

  [rows, cols] = size(x);
  out = zeros(size(x));

  % Handle 1D case
  if rows == 1
    x_1d = x;
    out_1d = zeros(1, cols);
    for i = 1:cols - w + 1
      out_1d(i) = median(x_1d(i:i+w-1));
    end
    out = out_1d;
    return;
  end

  % Process each row
  for r = 1:rows
    row = x(r, :);
    out_row = zeros(1, cols);
    for c = 1:cols - w + 1
      out_row(c) = median(row(c:c+w-1));
    end
    out(r, :) = out_row;
  end
end

