function out = sliding_window(x, w)
  if w <= 0
    error("Window width w must be positive");
  end

  out = zeros(size(x));
  n = length(x);
  valid_windows = (n >= w);

  if valid_windows
    for i = 1:(n - w + 1)
      out(i) = sum(x(i:(i + w - 1)));
    end
  else
    out = [];
  end
end

function out = reduce_along_dim(A, k)
  % REDUCE_ALONG_DIM Returns the k-th largest value in each column.
  % Ties are counted separately (e.g., if a column has [5, 5, 3] and k=2,
  % the result is 5).
  % Input orientation is preserved.

  [m, n] = size(A);
  out = zeros(m, n);

  for col = 1:n
    col_data = A(:, col);
    % Sort in descending order
    sorted_col = sort(col_data, 'descend');
    out(:, col) = sorted_col(k);
  end
end

