function out = signal_identity(x)
  % SIGNAL_IDENTITY FFT-based real circular autocorrelation without for/while loops.
  % Preserves input orientation.

  % Compute the FFT of the input signal
  X = fft(x);

  % Compute the squared magnitude of the FFT
  Pxx = abs(X).^2;

  % Compute the inverse FFT to get the autocorrelation
  out = ifft(Pxx);

  % Ensure the output is real (due to numerical precision)
  out = imag(out);
end

